Value.Calculation:
Let(
[
AddonUUID = BarcodeGenerator::CurrentAddonUUID;
Config = BarcodeGeneratorConfig ( AddonUUID );

initialProps = JSONSetElement ("";
      ["Config"; Config; JSONObject];
      ["AddonUUID"; AddonUUID; JSONString];
      ["ShowConfig"; True; JSONBoolean];
         // ---Optional---
      ["Meta.System.Appearance" ; Get(システムの外観) ; JSONString];
      ["Meta.System.Platform" ; Get(システムプラットフォーム) ; JSONString];
      ["Meta.Application.Version" ; Get(アプリケーションバージョン) ; JSONString];
      ["Meta.Application.Language" ; Get(アプリケーション言語) ; JSONString];
      ["Other.message"; "I am an initialProp" ; JSONString]


    )


];

initialProps 

)

Let(
[
Layouts =  LayoutNames ( Get(ファイル名 ) );
Layouts = "[\"" & Substitute ( Layouts ; "¶" ; "\",\"" ) & "\"]"

];


Layouts

)

Let(
[
Scripts =  ScriptNames ( Get(ファイル名 ) );
Scripts = "[\"" & Substitute ( Scripts ; "¶" ; "\",\"" ) & "\"]"

];


Scripts

)

Let(
[
ValueLists =  ValueListNames ( Get(ファイル名 ) );
ValueLists = "[\"" & Substitute ( ValueLists ; "¶" ; "\",\"" ) & "\"]"

];


ValueLists

)

While ( 
[ 
lName =  $OriginalLayout ;
tableName = $tableName ;


//Setup intial values
fields = FieldNames ( Get(ファイル名) ; lName );
n=0;
thisField = "";
fullName = "";
allFields = "";
c = ValueCount ( fields );
type ="";
dataType ="";
textFields = "";
dateFields = "";
timeFields = "";
timeStampFields = "";
containerFields = "";
numberFields = ""


] ; 

// CONDITION as long as n is less than c
n<c

; 

[  

//LOGIC
n=n+1;
thisField = GetValue(fields; n);
fullName = If(PatternCount(thisField; "::")=0; tableName & "::" & thisField );
allFields = List(allFields;fullName);
type = FieldType ( Get(ファイル名) ; fullName );
dataType = MiddleWords ( type; 2;1 );

textFields = If(dataType = "text"; List(textFields;fullName)  ; textFields );
numberFields = If(dataType = "number"; List(numberFields;fullName)  ; numberFields );
dateFields = If(dataType = "date"; List(dateFields;fullName)  ; dateFields );
timeFields = If(dataType = "time"; List(timeFields;fullName)  ; timeFields );
timeStampFields = If(dataType = "TimeStamp"; List(timeStampFields;fullName)  ; timeStampFields );
containerFields = If(dataType = "Container"; List(containerFields;fullName)  ; containerFields );
containerFields = If(dataType = "Open"; List(containerFields;fullName) ; containerFields );
containerFields = If(dataType = "Secure"; List(containerFields;fullName) ; containerFields );
iDfieldType = List(textFields; numberFields)

] ; 

//FINAL RESULT

  JSONSetElement ( "" ; 

   ["all";         If(ValueCount(allFields)>0;  "[\"" &   Substitute ( allFields; "¶"; "\",\"") & "\"]" ; "[]" )   ; JSONArray];
   ["number";      If(ValueCount(numberFields)>0;  "[\"" &   Substitute ( numberFields; "¶"; "\",\"") & "\"]" ; "[]" )   ; JSONArray];
   ["text";        If(ValueCount(textFields)>0;  "[\"" &   Substitute ( textFields; "¶"; "\",\"") & "\"]"; "[]" )   ; JSONArray];
   ["date";        If(ValueCount(dateFields)>0;  "[\"" &   Substitute ( dateFields; "¶"; "\",\"") & "\"]"; "[]" )   ; JSONArray];
   ["time";        If(ValueCount(timeFields)>0;  "[\"" &   Substitute ( timeFields; "¶"; "\",\"") & "\"]"  ; "[]" )  ; JSONArray];
   ["timeStamp";   If(ValueCount(timeStampFields)>0;  "[\"" &   Substitute ( timeStampFields; "¶"; "\",\"") & "\"]" ; "[]" )   ; JSONArray];
   ["container";   If(ValueCount(containerFields)>0;  "[\"" &   Substitute ( containerFields; "¶"; "\",\"") & "\"]" ; "[]" )   ; JSONArray] ;
   ["id";          If(ValueCount(iDfieldType)>0;  "[\"" &   Substitute ( iDfieldType; "¶"; "\",\"") & "\"]" ; "[]" )   ; JSONArray]



  )
)

While (
[
prefix = $Prefx; 
l = Length(prefix);
objects = LayoutObjectNames ( Get(ファイル名) ; Get(レイアウト名) );
n = 1;
thisObject = GetValue(objects;1);
result = ""
];

not IsEmpty ( thisObject );
[
thisObjectsType = GetLayoutObjectAttribute ( thisObject ; "objectType" );
isWebViewer = thisObjectsType = "web viewer";
matchesPrefix = Left(thisObject; l) = prefix;
result = If( (isWebViewer and matchesPrefix) ; List(result; thisObject; );result );
n = n+1;
thisObject = GetValue(objects;n)

];
result
)

JSONSetElement ("";
      ["Config"; $Config; JSONObject];
      ["AddonUUID"; $AddonUUID; JSONString];
      ["Meta.User.PrivilegeSetName" ; Get(現在のアクセス権セット名) ; JSONString];
         // ---Optional---
      ["ShowConfig"; $ShowConfig; JSONBoolean];
      ["Meta.System.Appearance" ; Get(システムの外観) ; JSONString];
      ["Meta.System.Platform" ; Get(システムプラットフォーム) ; JSONString];
      ["Meta.Application.Version" ; Get(アプリケーションバージョン) ; JSONString];
      ["Meta.Application.Language" ; Get(アプリケーション言語) ; JSONString];
      ["Other.message"; "I am an initialProp" ; JSONString]

 )

Result.Calculation:
Let(
[k1 = "受注データ::紙質";
k2 = "受注データ::メーカー";
k3 = "受注データ::品名";
k4 = "受注データ::規格";
k5 = "受注データ::サイズ";
c = GetField ( Get ( レイアウトテーブル名 )&"::xパーツ目")
];
Case ( c = "1"; GetField ( k1&"1" ) &", "& GetField ( k2&"1" ) &", "& GetField ( k3&"1" ) &", "&GetField ( k4&"1" ) &", "& GetField ( k5&"1" );
 c = "2"; GetField ( k1&"2" ) &", "& GetField ( k2&"2" ) &", "& GetField ( k3&"2" ) &", "&GetField ( k4&"2" ) &", "& GetField ( k5&"2" );
 c = "3"; GetField ( k1&"3" ) &", "& GetField ( k2&"3" ) &", "& GetField ( k3&"3" ) &", "&GetField ( k4&"3" ) &", "& GetField ( k5&"3" );
 c = "4"; GetField ( k1&"4" ) &", "& GetField ( k2&"4" ) &", "& GetField ( k3&"4" ) &", "&GetField ( k4&"4" ) &", "& GetField ( k5&"4" );
 c = "5"; GetField ( k1&"5" ) &", "& GetField ( k2&"5" ) &", "& GetField ( k3&"5" ) &", "&GetField ( k4&"5" ) &", "& GetField ( k5&"5" );
 c = "6"; GetField ( k1&"6" ) &", "& GetField ( k2&"6" ) &", "& GetField ( k3&"6" ) &", "&GetField ( k4&"6" ) &", "& GetField ( k5&"6" );
 c = "7"; GetField ( k1&"7" ) &", "& GetField ( k2&"7" ) &", "& GetField ( k3&"7" ) &", "&GetField ( k4&"7" ) &", "& GetField ( k5&"7" );
 c = "8"; GetField ( k1&"8" ) &", "& GetField ( k2&"8" ) &", "& GetField ( k3&"8" ) &", "&GetField ( k4&"8" ) &", "& GetField ( k5&"8" );
 c = "9"; GetField ( k1&"9" ) &", "& GetField ( k2&"9" ) &", "& GetField ( k3&"9" ) &", "&GetField ( k4&"9" ) &", "& GetField ( k5&"9" );
 c = "10"; GetField ( k1&"0" ) &", "& GetField ( k2&"0" ) &", "& GetField ( k3&"0" ) &", "&GetField ( k4&"0" ) &", "& GetField ( k5&"0" );


)


)

